package scanner

import (
	"context"
	"io/fs"
	"path"
	"runtime"
	"sort"
	"strings"
	"time"

	"github.com/navidrome/navidrome/consts"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
)

type dirStats struct {
	Path            string
	ModTime         time.Time
	Images          []string
	ImagesUpdatedAt time.Time
	HasPlaylist     bool
	AudioFilesCount uint32
}

func walkDirTree(ctx context.Context, filesystem fs.FS, rootFolder string) (<-chan dirStats, chan error) {
	results := make(chan dirStats, 5000)
	errors := make(chan error, 1)
	go func() {
		err := walkFolder(ctx, filesystem, rootFolder, results)
		if err != nil {
			log.Error(ctx, "Error loading directory tree", err)
		}
		close(results)
		errors <- err
		close(errors)
	}()
	return results, errors
}

func walkFolder(ctx context.Context, filesystem fs.FS, currentFolder string, results chan<- dirStats) error {
	children, stats, err := loadDir(ctx, filesystem, currentFolder)
	if err != nil {
		return err
	}
	for _, c := range children {
		err := walkFolder(ctx, filesystem, c, results)
		if err != nil {
			return err
		}
	}

	dir := path.Clean(currentFolder)
	log.Trace(ctx, "Found directory", "dir", dir, "audioCount", stats.AudioFilesCount,
		"images", stats.Images, "hasPlaylist", stats.HasPlaylist)
	stats.Path = dir
	results <- *stats

	return nil
}

func loadDir(ctx context.Context, filesystem fs.FS, dirPath string) ([]string, *dirStats, error) {
	var children []string
	stats := &dirStats{}

	dirInfo, err := fs.Stat(filesystem, dirPath)
	if err != nil {
		log.Error(ctx, "Error stating dir", "path", dirPath, err)
		return nil, nil, err
	}
	stats.ModTime = dirInfo.ModTime()

	dir, err := filesystem.Open(dirPath)
	if err != nil {
		log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
		return children, stats, err
	}
	defer dir.Close()

	var dirEntries []fs.DirEntry
	if readDirFile, ok := dir.(fs.ReadDirFile); ok {
		dirEntries = fullReadDir(ctx, readDirFile)
	} else {
		dirEntries, err = fs.ReadDir(filesystem, dirPath)
		if err != nil {
			return children, stats, err
		}
	}
	for _, entry := range dirEntries {
		isDir, err := isDirOrSymlinkToDir(filesystem, dirPath, entry)
		// Skip invalid symlinks
		if err != nil {
			log.Error(ctx, "Invalid symlink", "dir", path.Join(dirPath, entry.Name()), err)
			continue
		}
		if isDir && !isDirIgnored(filesystem, dirPath, entry) && isDirReadable(filesystem, dirPath, entry) {
			children = append(children, path.Join(dirPath, entry.Name()))
		} else {
			fileInfo, err := entry.Info()
			if err != nil {
				log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
				return children, stats, err
			}
			if fileInfo.ModTime().After(stats.ModTime) {
				stats.ModTime = fileInfo.ModTime()
			}
			switch {
			case model.IsAudioFile(entry.Name()):
				stats.AudioFilesCount++
			case model.IsValidPlaylist(entry.Name()):
				stats.HasPlaylist = true
			case model.IsImageFile(entry.Name()):
				stats.Images = append(stats.Images, entry.Name())
				if fileInfo.ModTime().After(stats.ImagesUpdatedAt) {
					stats.ImagesUpdatedAt = fileInfo.ModTime()
				}
			}
		}
	}
	return children, stats, nil
}

// fullReadDir reads all files in the folder, skipping the ones with errors.
// It also detects when it is "stuck" with an error in the same directory over and over.
// In this case, it and returns whatever it was able to read until it got stuck.
// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
func fullReadDir(ctx context.Context, dir fs.ReadDirFile) []fs.DirEntry {
	var allDirs []fs.DirEntry
	var prevErrStr = ""
	for {
		dirs, err := dir.ReadDir(-1)
		allDirs = append(allDirs, dirs...)
		if err == nil {
			break
		}
		log.Warn(ctx, "Skipping DirEntry", err)
		if prevErrStr == err.Error() {
			log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
			break
		}
		prevErrStr = err.Error()
	}
	sort.Slice(allDirs, func(i, j int) bool { return allDirs[i].Name() < allDirs[j].Name() })
	return allDirs
}

// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
// system directory, or a symbolic link to a directory. Note that if the dirEnt
// is not a directory but is a symbolic link, this method asks the filesystem
// to follow the symbolic link.
// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
// efficiency for go 1.16 and beyond
func isDirOrSymlinkToDir(filesystem fs.FS, baseDir string, dirEnt fs.DirEntry) (bool, error) {
	if dirEnt.IsDir() {
		return true, nil
	}
	if dirEnt.Type()&fs.ModeSymlink == 0 {
		return false, nil
	}
	// Does this symlink point to a directory?
	fileInfo, err := fs.Stat(filesystem, path.Join(baseDir, dirEnt.Name()))
	if err != nil {
		return false, err
	}
	return fileInfo.IsDir(), nil
}

// isDirIgnored returns true if the directory represented by dirEnt contains an
// `ignore` file (named after consts.SkipScanFile)
func isDirIgnored(filesystem fs.FS, baseDir string, dirEnt fs.DirEntry) bool {
	// allows Album folders for albums which e.g. start with ellipses
	name := dirEnt.Name()
	if strings.HasPrefix(name, ".") && !strings.HasPrefix(name, "..") {
		return true
	}
	if runtime.GOOS == "windows" && strings.EqualFold(name, "$RECYCLE.BIN") {
		return true
	}
	_, err := fs.Stat(filesystem, path.Join(baseDir, name, consts.SkipScanFile))
	return err == nil
}

// isDirReadable returns true if the directory represented by dirEnt is readable
func isDirReadable(filesystem fs.FS, baseDir string, dirEnt fs.DirEntry) bool {
	dirPath := path.Join(baseDir, dirEnt.Name())
	dir, err := filesystem.Open(dirPath)
	if err != nil {
		log.Warn("Skipping unreadable directory", "path", dirPath, err)
		return false
	}
	if err := dir.Close(); err != nil {
		log.Error("Error closing directory", "path", dirPath, err)
	}
	return true
}

// - If the playlist is in the DB and sync == true, import it, or else skip it
// Delete all empty albums, delete all empty artists, clean-up playlists
func (s *TagScanner) Scan(ctx context.Context, lastModifiedSince time.Time, progress chan uint32) (int64, error) {
	ctx = auth.WithAdminUser(ctx, s.ds)
	start := time.Now()

	// Special case: if lastModifiedSince is zero, re-import all files
	fullScan := lastModifiedSince.IsZero()

	// If the media folder is empty (no music and no subfolders), abort to avoid deleting all data from DB
	filesystem := os.DirFS(s.rootFolder)
	empty, err := isDirEmpty(ctx, filesystem, ".")
	if err != nil {
		return 0, err
	}
	if empty && !fullScan {
		log.Error(ctx, "Media Folder is empty. Aborting scan.", "folder", s.rootFolder)
		return 0, nil
	}

	allDBDirs, err := s.getDBDirTree(ctx)
	if err != nil {
		return 0, err
	}

	allFSDirs := dirMap{}
	var changedDirs []string
	s.cnt = &counters{}
	genres := newCachedGenreRepository(ctx, s.ds.Genre(ctx))
	s.mapper = newMediaFileMapper(s.rootFolder, genres)
	refresher := newRefresher(s.ds, s.cacheWarmer, allFSDirs)

	walkerStart := time.Now()
	log.Trace(ctx, "Loading directory tree from music folder", "folder", s.rootFolder)
	foldersFound, walkerError := walkDirTree(ctx, filesystem, ".")
	for folderStats := range foldersFound {
		folderStats.Path = filepath.Join(s.rootFolder, filepath.FromSlash(folderStats.Path))
		progress <- folderStats.AudioFilesCount
		allFSDirs[folderStats.Path] = folderStats

		if s.folderHasChanged(folderStats, allDBDirs, lastModifiedSince) {
			changedDirs = append(changedDirs, folderStats.Path)
			log.Debug("Processing changed folder", "dir", folderStats.Path)
			err := s.processChangedDir(ctx, refresher, fullScan, folderStats.Path)
			if err != nil {
				log.Error("Error updating folder in the DB", "dir", folderStats.Path, err)
			}
		}
	}

	if err := <-walkerError; err != nil {
		log.Error("There were errors reading directories from filesystem", err)
		log.Error("Scan was interrupted by error. See errors above", err)
		return 0, err
	}
	log.Debug("Finished reading directories from filesystem", "elapsed", time.Since(walkerStart))

	deletedDirs := s.getDeletedDirs(ctx, allFSDirs, allDBDirs)
	if len(deletedDirs)+len(changedDirs) == 0 {
		log.Debug(ctx, "No changes found in Music Folder", "folder", s.rootFolder, "elapsed", time.Since(start))
		return 0, nil
	}

	for _, dir := range deletedDirs {
		err := s.processDeletedDir(ctx, refresher, dir)
		if err != nil {
			log.Error("Error removing deleted folder from DB", "dir", dir, err)
		}
	}

	s.cnt.playlists = 0
	if conf.Server.AutoImportPlaylists {
		// Now that all mediafiles are imported/updated, search for and import/update playlists
		u, _ := request.UserFrom(ctx)
		for _, dir := range changedDirs {
			info := allFSDirs[dir]
			if info.HasPlaylist {
				if !u.IsAdmin {
					log.Warn("Playlists will not be imported, as there are no admin users yet, "+
						"Please create an admin user first, and then update the playlists for them to be imported", "dir", dir)
				} else {
					s.cnt.playlists = s.plsSync.processPlaylists(ctx, dir)
				}
			}
		}
	} else {
		log.Debug("Playlist auto-import is disabled")
	}

	err = s.ds.GC(log.NewContext(ctx), s.rootFolder)
	log.Info("Finished processing Music Folder", "folder", s.rootFolder, "elapsed", time.Since(start),
		"added", s.cnt.added, "updated", s.cnt.updated, "deleted", s.cnt.deleted, "playlistsImported", s.cnt.playlists)

	return s.cnt.total(), err
}

func isDirEmpty(ctx context.Context, filesystem fs.FS, dir string) (bool, error) {
	children, stats, err := loadDir(ctx, filesystem, dir)
	if err != nil {
		return false, err
	}
	return len(children) == 0 && stats.AudioFilesCount == 0, nil
}

func (s *TagScanner) getDBDirTree(ctx context.Context) (map[string]struct{}, error) {
	start := time.Now()
	log.Trace(ctx, "Loading directory tree from database", "folder", s.rootFolder)

	repo := s.ds.MediaFile(ctx)
	dirs, err := repo.FindPathsRecursively(s.rootFolder)
	if err != nil {
		return nil, err
	}
	resp := map[string]struct{}{}
	for _, d := range dirs {
		resp[filepath.Clean(d)] = struct{}{}
	}

	log.Debug("Directory tree loaded from DB", "total", len(resp), "elapsed", time.Since(start))
	return resp, nil
}

func (s *TagScanner) folderHasChanged(folder dirStats, dbDirs map[string]struct{}, lastModified time.Time) bool {
	_, inDB := dbDirs[folder.Path]
	// If is a new folder with at least one song OR it was modified after lastModified
	return (!inDB && (folder.AudioFilesCount > 0)) || folder.ModTime.After(lastModified)
}

