// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
// efficiency for go 1.16 and beyond
func isDirOrSymlinkToDir(filesystem fs.FS, baseDir string, dirEnt fs.DirEntry) (bool, error) {
	if dirEnt.IsDir() {
		return true, nil
	}
	if dirEnt.Type()&fs.ModeSymlink == 0 {
		return false, nil
	}
	// Does this symlink point to a directory?
	fileInfo, err := fs.Stat(filesystem, path.Join(baseDir, dirEnt.Name()))
	if err != nil {
		return false, err
	}
	return fileInfo.IsDir(), nil
}

// isDirIgnored returns true if the directory represented by dirEnt contains an
// `ignore` file (named after consts.SkipScanFile)
func isDirIgnored(filesystem fs.FS, baseDir string, dirEnt fs.DirEntry) bool {
	// allows Album folders for albums which e.g. start with ellipses
	name := dirEnt.Name()
	if strings.HasPrefix(name, ".") && !strings.HasPrefix(name, "..") {
		return true
	}
	if runtime.GOOS == "windows" && strings.EqualFold(name, "$RECYCLE.BIN") {
		return true
	}
	_, err := fs.Stat(filesystem, path.Join(baseDir, name, consts.SkipScanFile))
	return err == nil
}

// isDirReadable returns true if the directory represented by dirEnt is readable
func isDirReadable(filesystem fs.FS, baseDir string, dirEnt fs.DirEntry) bool {
	dirPath := path.Join(baseDir, dirEnt.Name())
	dir, err := filesystem.Open(dirPath)
	if err != nil {
		log.Warn("Skipping unreadable directory", "path", dirPath, err)
		return false
	}
	if err := dir.Close(); err != nil {
		log.Error("Error closing directory", "path", dirPath, err)
	}
	return true
}
